import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("statement export", () => {
  test("statement export", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.exportStatement(pg_uma, p_ada)).toBe("number,date,amount,figure,status\n");
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    expect(await ui.exportStatement(pg_vic, p_ada)).toBe("number,date,amount,figure,status\nFY2026-1,2026-03-01,10.00,1.00,SETTLED\nFY2026-2,2026-03-10,20.00,2.00,OPEN\n");
    await ui.refresh(pg_uma);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    expect(await ui.exportStatement(pg_uma, p_ada)).toBe("number,date,amount,figure,status\nFY2026-1,2026-03-01,10.00,1.00,SETTLED\nFY2026-2,2026-03-10,20.00,2.00,OPEN\nFY2026-3,2026-03-10,30.00,6.00,OPEN\n");
  });
  test("statement export scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "grace-days", "3");
    await ui.setSetting(pg_uma, "note-threshold", "2.50");
    expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
    await ui.loadSheet(pg_uma, sheet);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "12.50", "note": "tpl"})).toBe(true);
    await ui.setSetting(pg_uma, "fiscal-start-month", "7");
    await ui.setSetting(pg_uma, "alert-threshold", "1.00");
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-10", "half-up")).toBe(true);
    await ui.setSetting(pg_uma, "review-threshold", "1.50");
    await ui.setSetting(pg_uma, "escalate-after", "1");
    await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "tags": "a"})).toBeNull();
  await r.getByTestId('person-approver-input').fill(user);
  await r.getByTestId('person-approver-save').click();
  return until(page, done, r.getByTestId('person-error'), 'set approver', already);
}

/** Undo the transfer that brought the person here: true once the row is gone. */
export async function transferUndo(page: Page, personId: string): Promise<boolean> {
  const r = row(page, personId);
  await r.getByTestId('person-transfer-undo').click();
  return until(page, async () => (await r.count()) === 0, r.getByTestId('person-error'), 'transfer undo');
}

export async function exportStatement(page: Page, personId: string): Promise<string> {
  const [download] = await Promise.all([page.waitForEvent('download'), row(page, personId).getByTestId('person-export-statement').click()]);
  const path = await download.path();
  if (!path) throw new Error('export produced no file');
  return readFileSync(path, 'utf8');
}

/** Undo the last merge into this person: true once the merged person's row is back (one more row). */
export async function mergeUndo(page: Page, personId: string): Promise<boolean> {
  const r = row(page, personId);
  const was = await rows(page).count();
  await r.getByTestId('person-merge-undo').click();
  return until(page, async () => (await rows(page).count()) > was, r.getByTestId('person-error'), 'merge undo');
}

/** Hold the selected people together: how many were held. */
export async function bulkHold(page: Page, personIds: string[], f: { from?: string; to?: string }): Promise<number | null> {
  for (const id of personIds) await row(page, id).getByTestId('person-select').setChecked(true);
  await setField(page, 'bulk-hold-from', f.from);
  await setField(page, 'bulk-hold-to', f.to);
  const was = await shown(page.getByTestId('bulk-held'));
  await page.getByTestId('bulk-hold').click();
  const n = await countAfter(page, page.getByTestId('bulk-held'), page.getByTestId('person-error'), 'bulk hold', was);
  return n === null ? null : Number(n);
}

export async function exportPerson(page: Page, personId: string): Promise<string> {
  const [download] = await Promise.all([page.waitForEvent('download'), row(page, personId).getByTestId('person-export').click()]);
  const path = await download.path();
  if (!path) throw new Error('export produced no file');
  return readFileSync(path, 'utf8');
}

/** Give the selected people a grade together: how many were changed. */
export async function bulkGrade(page: Page, personIds: string[], f: { grade: string; from?: string }): Promise<number | null> {
  for (const id of personIds) await row(page, id).getByTestId('person-select').setChecked(true);
  await page.getByTestId('bulk-grade').selectOption(f.grade);
  await setField(page, 'bulk-grade-from', f.from);
  const was = await shown(page.getByTestId('bulk-graded'));

